<script setup lang="ts">
import {computed} from 'vue'
import {Modal as AModal,Descriptions as ADescriptions,DescriptionsItem as ADescriptionsItem} from 'ant-design-vue'
import {timeQualities,type LogDocument} from '../syslog'
import {formatTime} from '../types'
import StatePanel from './StatePanel.vue'
import ByteViewer from './ByteViewer.vue'
const props=defineProps<{open:boolean;document:LogDocument|null;pending:boolean;error:string}>(),emit=defineEmits<{close:[];retry:[]}>()
const original=computed(()=>JSON.stringify({payload:props.document?.record.raw_base64??''}))
</script>
<template><a-modal title="日志详情" :open="open" :width="980" destroy-on-close @cancel="emit('close')"><StatePanel :loading="pending" :error="error" @retry="emit('retry')"><template v-if="document"><a-alert type="info" show-icon message="原文查看已登记操作审计。传输对端经过接收器验证；原文中的主机名和应用名仅为发送方声明。" class="section-gap"/><a-descriptions :column="1" bordered size="small"><a-descriptions-item label="事件标识"><span class="technical digest">{{document.event_id}}</span></a-descriptions-item><a-descriptions-item label="来源 / 网络域">{{document.record.binding.source_name}} / {{document.record.binding.network_domain}}</a-descriptions-item><a-descriptions-item label="接入探针">{{document.sensor_id}}</a-descriptions-item><a-descriptions-item label="接收 / 平台入站">{{formatTime(document.record.observed_at)}} / {{formatTime(document.received_at)}}</a-descriptions-item><a-descriptions-item label="来源时间">{{document.parsed.source_time?formatTime(document.parsed.source_time):'无法确定'}} · {{timeQualities[document.parsed.time_quality]}}</a-descriptions-item><a-descriptions-item label="传输对端">{{document.record.peer.ip}}:{{document.record.peer.port}} · {{document.record.binding.transport.toUpperCase()}}</a-descriptions-item><a-descriptions-item label="原文声明">主机 {{document.parsed.hostname||'未提供'}} · 应用 {{document.parsed.application||'未提供'}}</a-descriptions-item><a-descriptions-item label="解析状态">{{document.parsed.state==='parsed'?'解析成功':'解析隔离'}} · {{document.parsed.parser_version}}</a-descriptions-item><a-descriptions-item label="PRI / Facility / Severity">{{document.parsed.priority??'—'}} / {{document.parsed.facility??'—'}} / {{document.parsed.severity??'—'}}</a-descriptions-item><a-descriptions-item label="来源序列"><span class="technical">{{document.record.source_epoch}} / {{document.record.source_sequence}}</span></a-descriptions-item><a-descriptions-item label="原文 SHA-256"><span class="technical digest">{{document.record.raw_sha256}}</span></a-descriptions-item></a-descriptions><p class="page-description section-gap">{{document.parsed.state==='quarantined'?'原始消息已保存，尚未形成可用的标准解析字段。':'来源时间与接收时间分别保存，不根据日志文本授予处置权限。'}}</p><pre v-if="document.parsed.state==='parsed'" class="log-message">{{document.parsed.message}}</pre><ByteViewer :original="original" source="syslog"/></template></StatePanel><template #footer><a-button @click="emit('close')">关闭</a-button></template></a-modal></template>
<style scoped>.digest{overflow-wrap:anywhere}.log-message{white-space:pre-wrap;overflow-wrap:anywhere;max-height:240px;overflow:auto;background:var(--table-header);border:1px solid var(--line);border-radius:6px;padding:var(--panel-inset);font:inherit}</style>
